var health: int = 100
var max_health: int = 100
var attack_power: int = 20
var enemy_health: int = 60
var enemy_max_health: int = 60
var enemy_attack: int = 15

func attack() -> bool:
	enemy_health -= attack_power
	if enemy_health < 0:
		enemy_health = 0
	return enemy_health == 0

func take_damage(amount: int) -> void:
	health -= amount
	if health < 0:
		health = 0

func is_alive() -> bool:
	return health > 0

func enemy_turn() -> bool:
	take_damage(enemy_attack)
	return is_alive()

func spawn_enemy(hp: int, power: int) -> void:
	enemy_health = hp
	enemy_max_health = hp
	enemy_attack = power

func fight() -> String:
	while is_alive() and enemy_health > 0:
		if attack():
			return "won"
		if not enemy_turn():
			return "lost"
	return "lost"
